bounded_host_request.command:
set -eu
cid=gace-createvdobot-videobot-poll-1
docker exec -i "$cid" node --input-type=module <<'NODE'
import fs from 'node:fs';import pg from 'pg';
const pool=new pg.Pool({host:process.env.VIDEOBOT_DB_HOST,user:process.env.VIDEOBOT_DB_USER,database:process.env.VIDEOBOT_DB_NAME,password:fs.readFileSync('/run/secrets/videobot_db_password','utf8').trim(),max:1,connectionTimeoutMillis:4500});
let m=0;
try{
 const {rows:[x]}=await pool.query(`
 WITH protected AS (
 SELECT r.* ,l.paid_video_file_id,l.title,l.price_stars,l.seller_user_id
 FROM videobot_post_receipts r JOIN videobot_listings l USING (listing_id)
 WHERE r.delivery_key IN (SELECT DISTINCT delivery_key FROM videobot_stars_ledger WHERE kind='paid' AND delivery_key IS NOT NULL)
 ), duplicates AS (
 SELECT r.*,l.paid_video_file_id,l.title,l.price_stars,l.seller_user_id
 FROM videobot_post_receipts r JOIN videobot_listings l USING (listing_id)
 WHERE NOT EXISTS (SELECT 1 FROM videobot_stars_ledger p WHERE p.kind='paid' AND p.delivery_key=r.delivery_key)
 )
 SELECT
 (SELECT COUNT(*) FROM protected WHERE paid_message_id=4718 AND status='sent') exact_protected,
 (SELECT COUNT(*) FROM duplicates WHERE status='sent') posted_duplicates,
 (SELECT COUNT(*) FROM duplicates d JOIN protected p ON d.topic_id=p.topic_id AND d.status='sent') same_topic,
 (SELECT COUNT(*) FROM duplicates d JOIN protected p ON d.paid_video_file_id=p.paid_video_file_id AND d.status='sent') same_file,
 (SELECT COUNT(*) FROM duplicates d JOIN protected p ON d.title=p.title AND d.price_stars=p.price_stars AND d.seller_user_id=p.seller_user_id AND d.status='sent') same_product_title,
 (SELECT COUNT(*) FROM duplicates WHERE status='sent' AND free_message_ids IS NOT NULL AND paid_message_id IS NOT NULL) complete_duplicate_receipts,
 (SELECT COUNT(*) FROM duplicates WHERE status='sent' AND updated_at>NOW()-interval '47 hours') recent_duplicates,
 (SELECT COUNT(DISTINCT buyer_user_id) FROM videobot_stars_ledger WHERE kind='paid' AND delivery_key IN (SELECT delivery_key FROM protected)) paid_buyers
 `);
 const n=k=>Number(x[k]);
 if(n('exact_protected')===1)m|=1;
 if(n('posted_duplicates')>0)m|=2;
 if(n('posted_duplicates')===n('same_topic'))m|=4;
 if(n('posted_duplicates')===n('same_file'))m|=8;
 if(n('posted_duplicates')===n('same_product_title'))m|=16;
 if(n('posted_duplicates')===n('complete_duplicate_receipts'))m|=32;
 if(n('posted_duplicates')===n('recent_duplicates'))m|=64;
 if(n('paid_buyers')>0)m|=128;
}finally{await pool.end()}
process.exit(m);
NODE
